mapper.sql:
EXISTS ( SELECT 1 FROM( SELECT I.TARGETID FROM T_CORE_BPMN_INST I, T_CORE_BPMN_INST_TASK K, T_CORE_BPMN_INST_TASK_ROLE R, T_CORE_ROLE_USER U WHERE I.ID = K.INSTID AND K.ID = R.INSTTASKID AND R.ROLEID = U.ROLEID AND ( K.COUNTERSIGN = '0' /* 会签时所有人员都要进行审核 */ OR NOT EXISTS ( SELECT 1 FROM T_CORE_BPMN_COMMENT C WHERE C.CREATEDTIME >= K.CREATEDTIME AND C.TASKID = K.TASKID AND C.TARGETID = I.TARGETID AND U.USERID = C.USERID ) )
AND K.STATUSCODE = #{bpmn_statusCode}
AND U.USERID = #{loginUser.id} UNION ALL SELECT I.TARGETID FROM T_CORE_BPMN_INST I, T_CORE_BPMN_INST_TASK K, T_CORE_BPMN_INST_TASK_USER U WHERE I.ID = K.INSTID AND K.ID = U.INSTTASKID
AND K.STATUSCODE = #{bpmn_statusCode}
AND U.USERID = #{loginUser.id}) Z WHERE Z.TARGETID = ('${service_table}$' || T.ID) )
